    /**
     * Master Encryption Key that wraps vault keys (32 bytes).
     */
    public var mek: Data

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * Authentication key for SRP-6a (32 bytes).
         */authKey: Data, 
        /**
         * Master Encryption Key that wraps vault keys (32 bytes).
         */mek: Data) {
        self.authKey = authKey
        self.mek = mek
    }
}

