extension SubKeys: Sendable {}
#endif


extension SubKeys: Equatable, Hashable {
    public static func ==(lhs: SubKeys, rhs: SubKeys) -> Bool {
        if lhs.authKey != rhs.authKey {
            return false
        }
        if lhs.mek != rhs.mek {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(authKey)
        hasher.combine(mek)
    }
}



